export const darkTheme = {
  createButton: (label) => ({ style: 'dark', label, render: () => `<button>${label}</button>` }),
  createSlider: (min, max) => ({ style: 'dark', min, max }),
};

export function buildForm(factory) {
  return [factory.createButton('Save'), factory.createSlider(0, 100)];
}
